const playwright = $('Healthcheck – Playwright Server').item.json;
const metrics = $('Récupérer métriques (DB)').item.json;
const queue = $('Status de la queue (DB)').item.json;

const ALERT_THRESHOLDS = {
  maxErrorsPerHour: 5,
  maxInvitesPerDay: 60,
  maxOverdueSteps: 10,
};

const alerts = [];
let severity = 'ok';

// Vérifier la santé du serveur Playwright
if (!playwright.status || playwright.status !== 'ok') {
  alerts.push('🔴 Playwright server DOWN ou unreachable');
  severity = 'critical';
}

// Trop d'erreurs
if (parseInt(metrics.errors_last_hour) >= ALERT_THRESHOLDS.maxErrorsPerHour) {
  alerts.push(`⚠️ ${metrics.errors_last_hour} erreurs dans la dernière heure (seuil: ${ALERT_THRESHOLDS.maxErrorsPerHour})`);
  severity = severity === 'critical' ? 'critical' : 'warning';
}

// Quota LinkedIn proche
if (parseInt(metrics.invites_today) >= ALERT_THRESHOLDS.maxInvitesPerDay * 0.9) {
  alerts.push(`⚠️ Quota LinkedIn à ${metrics.invites_today}/${ALERT_THRESHOLDS.maxInvitesPerDay} invitations`);
  severity = severity === 'critical' ? 'critical' : 'warning';
}

// Quota LinkedIn dépassé – mode veille
if (parseInt(metrics.invites_today) >= ALERT_THRESHOLDS.maxInvitesPerDay) {
  alerts.push(`🛑 Quota journalier LinkedIn ATTEINT – mode veille activé`);
  severity = 'critical';
}

// Étapes en retard
if (parseInt(queue.overdue_steps) >= ALERT_THRESHOLDS.maxOverdueSteps) {
  alerts.push(`⚠️ ${queue.overdue_steps} étapes de séquence en retard`);
  severity = severity === 'critical' ? 'critical' : 'warning';
}

const report = {
  timestamp: new Date().toISOString(),
  severity,
  hasAlerts: alerts.length > 0,
  alerts,
  metrics: {
    playwright: playwright.status,
    errorsLastHour: metrics.errors_last_hour,
    successLastHour: metrics.success_last_hour,
    invitesToday: metrics.invites_today,
    messagesToday: metrics.messages_today,
    pendingSequences: queue.pending_sequences,
    overdueSteps: queue.overdue_steps,
    linkedinCounters: playwright.counters,
  },
};

return [{ json: report }];

